declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationMetadataJsonAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationMetadataJsonAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationMetadataJsonAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getMetadataJson returns null on a freshly created holder.
     */
    public function testMetadataJsonNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationMetadataJsonAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isMetadataJsonAssigned());
        $this->assertNull($holder->getMetadataJson());
    }
}
class ImplWithUserInvitationMetadataJsonAttributeHolderUnitTest
{
    use UserInvitationMetadataJsonAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedMetadataJsonRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultMetadataJson();
    }
}
